/**
 * @file ProjectGrid.tsx
 * @description Responsive grid layout for displaying project cards with filtering
 * @module components/features
 * 
 * @requires framer-motion - For grid animations and transitions
 * @requires @/components/ui - For filter buttons and cards
 * 
 * Features:
 * - Responsive grid layout
 * - Category filtering
 * - Animated transitions
 * - Empty state handling
 * - Filter button highlighting
 * 
 * @example
 * ```tsx
 * // Basic usage
 * <ProjectGrid 
 *   projects={projectList}
 *   showFilters={true}
 * />
 * 
 * // With specific filter
 * <ProjectGrid 
 *   projects={projectList}
 *   filter="development"
 *   showFilters={false}
 * />
 * ```
 * 
 * @notes
 * - Grid adjusts columns based on screen size
 * - Animations use stagger effect for performance
 */

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { ProjectCard } from './ProjectCard';
import { fadeInUp, staggerContainer } from '@/lib/animations';
import { ProjectBase, ProjectCategory } from '@/types/content';

interface ProjectGridProps {
  projects: ProjectBase[];
  filter?: ProjectCategory | null;
  showFilters?: boolean;
  className?: string;
}

interface FilterButtonProps {
  active: boolean;
  onClick: () => void;
  children: React.ReactNode;
}

const FilterButton: React.FC<FilterButtonProps> = ({
  active,
  onClick,
  children
}) => (
  <motion.button
    onClick={onClick}
    className={`
      px-4 py-2 rounded-full transition-colors
      ${active 
        ? 'bg-primary-600 text-white' 
        : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
      }
    `}
    whileHover={{ scale: 1.05 }}
    whileTap={{ scale: 0.95 }}
  >
    {children}
  </motion.button>
);

export const ProjectGrid: React.FC<ProjectGridProps> = ({ 
  projects, 
  filter = null,
  showFilters = true,
  className = ''
}) => {
  const [activeFilter, setActiveFilter] = useState<ProjectCategory | null>(filter);
  
  // Get unique categories from projects
  const categories = Array.from(new Set(projects.map(project => project.category)));
  
  // Filter projects based on active filter
  const filteredProjects = activeFilter
    ? projects.filter(project => project.category === activeFilter)
    : projects;

  return (
    <div className={`space-y-8 ${className}`}>
      {/* Filter Categories */}
      {showFilters && categories.length > 0 && (
        <motion.div
          className="flex flex-wrap justify-center gap-2"
          variants={staggerContainer}
          initial="initial"
          animate="animate"
        >
          <FilterButton
            active={!activeFilter}
            onClick={() => setActiveFilter(null)}
          >
            All Projects
          </FilterButton>
          {categories.map(category => (
            <FilterButton
              key={category}
              active={activeFilter === category}
              onClick={() => setActiveFilter(category)}
            >
              {category}
            </FilterButton>
          ))}
        </motion.div>
      )}
      
      {/*
        Projects Grid.

        No AnimatePresence here, deliberately. It previously wrapped this list
        with mode="wait" - a single-child API - which starved incoming cards so
        each category rendered one unrelated project. Switching to sync mode
        traded that for the opposite failure: combined with `layout`, exiting
        cards never unmounted and filters only ever added, so "Technical
        Projects" displayed all six. A filtered list needs the DOM to match the
        filter; the exit flourish is not worth showing the wrong projects.
        Cards still animate in on mount.
      */}
      <motion.div
        className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8"
        variants={staggerContainer}
      >
        {filteredProjects.map(project => (
          <motion.div
            key={project.id}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.2 }}
          >
            <ProjectCard project={project} />
          </motion.div>
        ))}
      </motion.div>
      
      {/* Empty State */}
      {filteredProjects.length === 0 && (
        <motion.div 
          className="text-center py-12"
          variants={fadeInUp}
        >
          <p className="text-text-secondary">
            No projects found matching the selected filter.
          </p>
        </motion.div>
      )}
    </div>
  );
};